<?php
if(!defined('ABSPATH'))exit;
add_action('after_setup_theme',function(){add_theme_support('title-tag');add_theme_support('post-thumbnails');});
add_action('wp_enqueue_scripts',function(){wp_enqueue_style('impacthub',get_stylesheet_uri(),array(),'1.0.0');wp_enqueue_script('impacthub',get_template_directory_uri().'/app.js',array(),'1.0.0',true);});
function ih_content(){return array('ih_campaign'=>array(array('Nourish communities','Support access to nourishing food and community pantry programmes.','Food security',72,'♡'),array('Learning without limits','Explore access to educational resources, mentoring and learning opportunities.','Education',58,'✦'),array('Stronger neighbourhoods','Support community-led initiatives and inclusive local opportunities.','Community',85,'◎')),'ih_story'=>array(array('Building pathways to learning','An illustrative story about a neighbourhood learning programme and mentorship.','Education',0,'✦'),array('Food, dignity and connection','Explore an illustrative community food distribution initiative.','Food security',0,'♡'),array('Volunteers make the difference','Discover a sample story about volunteers supporting local projects.','Community',0,'◎')),'ih_programme'=>array(array('Education & skills','Learning opportunities, mentoring and skills development.','Education',0,'✦'),array('Food & wellbeing','Community nutrition and access to essential resources.','Food security',0,'♡'),array('Community development','Inclusive engagement and community-led development.','Community',0,'◎')));}
add_action('init',function(){foreach(array('ih_campaign'=>'Campaigns','ih_story'=>'Impact stories','ih_programme'=>'Programmes') as $key=>$label){register_post_type($key,array('label'=>$label,'public'=>true,'has_archive'=>true,'show_in_rest'=>true,'supports'=>array('title','editor','excerpt','thumbnail'),'menu_icon'=>'dashicons-heart'));}register_taxonomy('ih_topic',array_keys(ih_content()),array('label'=>'Topics','public'=>true,'show_in_rest'=>true));});
add_action('after_switch_theme',function(){if(get_option('ih_seeded_v1'))return;foreach(ih_content() as $type=>$entries){foreach($entries as $entry){$id=wp_insert_post(array('post_type'=>$type,'post_title'=>$entry[0],'post_content'=>$entry[1],'post_status'=>'publish'),true);if(!is_wp_error($id)){wp_set_object_terms($id,$entry[2],'ih_topic');update_post_meta($id,'ih_progress',$entry[3]);update_post_meta($id,'ih_icon',$entry[4]);}}}update_option('ih_seeded_v1',1);flush_rewrite_rules();});
function ih_cards($type){$q=new WP_Query(array('post_type'=>$type,'posts_per_page'=>-1,'orderby'=>'date','order'=>'ASC'));while($q->have_posts()){$q->the_post();$terms=wp_get_post_terms(get_the_ID(),'ih_topic',array('fields'=>'names'));$progress=max(0,min(100,(int)get_post_meta(get_the_ID(),'ih_progress',true)));?><article class="card"><div class="card-band" aria-hidden="true"><?php echo esc_html(get_post_meta(get_the_ID(),'ih_icon',true)?:'♡'); ?></div><span class="tag"><?php echo esc_html(is_wp_error($terms)?'':implode(' · ',$terms)); ?></span><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html(wp_strip_all_tags(get_the_content())); ?></p><?php if($type==='ih_campaign'):?><div class="progress" aria-label="<?php echo esc_attr($progress.'% illustrative goal'); ?>"><span style="width:<?php echo esc_attr($progress); ?>%"></span></div><div class="progress-label"><span>Illustrative goal progress</span><span><?php echo esc_html($progress); ?>%</span></div><?php endif; ?><p><a class="more" href="<?php the_permalink(); ?>">Explore details</a></p></article><?php }wp_reset_postdata();}
